function buildSystemPrompt(spec: AgentSpec): string {
  const parts: string[] = [];
  parts.push(`You are ${spec.role} (agent name: "${spec.name}").`);
  parts.push(`\n## MISSION\n${spec.mission}`);
  if (spec.duties.length) {
    parts.push(`\n## STANDING RESPONSIBILITIES\n${spec.duties.map((d, i) => `${i + 1}. ${d}`).join('\n')}`);
  }
  if (spec.mcps.length) {
    parts.push(
      `\n## EXTERNAL MCP SERVERS ATTACHED TO THIS RUN\n` +
        spec.mcps.map((m) => `- ${m}${MCP_PURPOSE[m] ? ` — ${MCP_PURPOSE[m]}` : ''}`).join('\n') +
        `\nThese servers expose tools to you (each tool is surfaced as \`<serverName>__<toolName>\`). When your task needs data or actions from one of these systems, call its tools. If a server is not reachable, say so instead of fabricating results.`,
    );
  }
  if (spec.skills.length) {
    const skillNames = spec.skills.map((s) => SKILL_NAMES[s] || s);
    parts.push(
      `\n## SKILLS ATTACHED TO THIS RUN\nSkill names: ${skillNames.join(', ')}.\nUse the \`list_skills\` tool to see the registered skills and their ids, then call \`use_skill\` to load the full instructions of any skill that matches the current task BEFORE doing that work. Follow the loaded skill for the rest of the matching task.`,
    );
  }
  parts.push(
    `\n## OPERATING PRINCIPLES
- You are an autonomous AI specialist. Complete the requested work end-to-end with the tools available to you.
- Prefer real data over guessing: when a task touches a system you have a tool for, CALL the tool.
- Keep all artifacts inside your designated workspace; never modify unrelated source files.
- When a step blocks on missing credentials or permissions, report it clearly and continue what you can.
- Finish with a concise, structured executive summary of what you did, what you found, and recommended next steps.`,
  );
  return parts.join('\n\n');
}

